template <class Mutex>
class lock_guard {
public:
    explicit lock_guard(Mutex& m);  // Implementation note: Compiler generates code to call m.lock() at runtime; if an exception occurs in m.lock(), it's propagated.
    lock_guard(Mutex& m, std::adopt_lock_t);  // Implementation note: Assumes m is already locked; no runtime lock acquisition, reducing overhead.
    ~lock_guard();  // Implementation note: Compiler ensures this is called on scope exit, invoking m.unlock() at runtime; in assembly, this might appear as a direct call to the unlock function.
    lock_guard(const lock_guard&) = delete;  // Implementation note: Compiler prevents compilation of code attempting to copy, enforcing compile-time error.
    lock_guard& operator=(const lock_guard&) = delete;  // Implementation note: Deleted to avoid runtime issues with mutex state.
private:
    Mutex& mut_;  // Typically a reference member; memory layout includes just this reference, minimizing footprint.
};
